# Standalone fail-closed verifier. Pure function, no imports, no IO.
# Accepts an optional witness argument; the witness is also embedded.

def verify(w=None):
    n = 3
    size = 1 << n          # 8 subsets
    nfam = 1 << size       # 256 families
    def popcount(v):
        c = 0
        while v:
            c += v & 1
            v >>= 1
        return c
    hered = []
    for F in range(nfam):
        ok = True
        for s in range(size):
            if (F >> s) & 1:
                for t in range(size):
                    if (t & s) == t and not ((F >> t) & 1):
                        ok = False
                        break
                if not ok:
                    break
        if ok:
            hered.append(F)
    # Dedekind number M(3) = 20, fail-closed count check
    if len(hered) != 20:
        return False
    for F in hered:
        best_i = 0
        for G in range(nfam):
            if (G & ~F) != 0:
                continue
            ok = True
            for a in range(size):
                if (G >> a) & 1:
                    for b in range(size):
                        if ((G >> b) & 1) and ((a & b) == 0):
                            ok = False
                            break
                    if not ok:
                        break
            if ok and popcount(G) > best_i:
                best_i = popcount(G)
        best_s = 0
        for x in range(n):
            cnt = 0
            for s in range(size):
                if ((F >> s) & 1) and ((s >> x) & 1):
                    cnt += 1
            if cnt > best_s:
                best_s = cnt
        if best_i != best_s:
            return False
    return True
